mapper.select:
SELECT id, shop_id, guide_code, completed, completed_at, create_time, update_time
FROM mt_h5_guide_state
WHERE shop_id = #{shopId}
  AND guide_code = #{guideCode}
LIMIT 1

mapper.insert:
INSERT INTO mt_h5_guide_state (
    shop_id, guide_code, completed, completed_at, create_time, update_time
) VALUES (
    #{shopId}, #{guideCode}, 1, #{completedAt}, #{completedAt}, #{completedAt}
)
ON DUPLICATE KEY UPDATE
    completed = 1,
    completed_at = COALESCE(completed_at, VALUES(completed_at)),
    update_time = VALUES(update_time)
